import{z as n,x as i,o as A,c as d,q as l,j as r,D as e,d as t,s as o,S as s,b as a}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"时序数据库的选型","description":"","frontmatter":{"title":"时序数据库的选型","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/de-tsdb-selection.md","filePath":"quant/de-tsdb-selection.md","lastUpdated":1791413859000}'),p={name:"quant/de-tsdb-selection.md"};function C(D,E,u,m,F,f){const B=i("Mermaid");return A(),d("div",null,[E[2]||(E[2]=l('<h1 id="时序数据库的选型" tabindex="-1">时序数据库的选型 <a class="header-anchor" href="#时序数据库的选型" aria-label="Permalink to &quot;时序数据库的选型&quot;">​</a></h1><div class="epigraph"><p>选型不是挑「最快的数据库」，而是先承认自己的查询只有几种形状，再找一个把弯路修在磁盘布局里的引擎。</p><footer>—— 据 Pelkonen 等, Gorilla: A Fast, Scalable, In-Memory Time Series Database, VLDB 2015；kdb+、ClickHouse、TimescaleDB 等引擎的公开文档整理</footer></div><p><a href="/quant/sl-map">上一课</a>把策略生命周期治理收成七条不变量，台账里的每个数字只引用数据的哈希——至于哈希底下数据住在哪、以什么形状住着，是治理交给下一门课程的问题。本课程写这台数据平台的工程。存储引擎的选型此前被<a href="/quant/fml-feature-store-deep">特征存储的深入</a>显式留白——那课声明「存储引擎与表格式选型是数据工程课程的对象」，本课接走这个问题：先定选型判据，随后三课沿入库前后的数据本体推进，行情怎么洗、公司行动怎么调、历史怎么版本化，再进平台单元。后课默认你已经知道数据住在哪、以什么形状住着。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>市场数据的写读形状与通用业务负载不同。写是 append-only 的洪流：逐笔成交与委托按事件时间到达，永不就地 UPDATE，一天动辄数亿条。读是少数几种固定形状的扫描：按标的乘日期段切片、按列取特征、按 as-of 取当时快照、按窗口滚动聚合、按日截面 rank。通用 OLTP 行存库为点查与事务优化，把 tick 塞进去，扫描带宽差出一两个数量级；反过来，为扫描优化的引擎不支持行级事务，把成交回传当业务表写会丢掉事件序。选型错的症状不是慢，而是查询形状与引擎假设不匹配——研究者只好在引擎外各补一层私有缓存，平台的真相从此不止一份。</p><p><span class="marginnote">术语翻译：as-of 查询就是「回到过去那一刻，取当时已知的最新状态」。比如今天想看 3 月 5 日研究时数据库里长什么样，就取所有 published_at 不晚于 3 月 5 日的行——不是取「关于 3 月 5 日、但可能上周才修正过的数据」。没有 as-of 语义，回测会不知不觉用未来修正值，这叫前视偏差。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选型判据五条，按序过。<strong>一，查询形状</strong>：把团队真实的查询收成五种以内，写不出清单就先改数据模型再谈选型。<strong>二，写入吞吐与有序性</strong>：摄取按到达序写入但研究按事件序读取，引擎要支持分区追加与迟到数据。<strong>三，压缩与扫描带宽</strong>：列存加 delta、Gorilla 类轻量编码，时间戳与价格列的压缩比和解压带宽直接决定回测速度。<strong>四，as-of 语义</strong>：能否把「取 published_at 不晚于 \\(t\\) 的最新行」写成一次顺序扫描，而不是每行一个子查询。<strong>五，生态与人力</strong>：团队能长期维护谁，比基准榜更硬。</p><p>候选谱系四档：通用关系库存日频与元数据够用；时序专用引擎运维轻、写路径好；列式分析引擎（ClickHouse，或对象存储上的 Parquet 加 Arrow 加 DuckDB）扫描最强；专用 tick 引擎（kdb+）带宽最高而许可与人才最贵。验收用自建基准——本团队五种查询乘真实数据量——不引用厂商跑分。</p>',9)),(A(),r(s,null,{default:e(()=>[o(B,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%94%B6%E9%9B%86%E7%9C%9F%E5%AE%9E%E6%9F%A5%E8%AF%A2%E5%BD%A2%E7%8A%B6%22%5D%20--%3E%20J%7B%22%E4%BA%94%E7%A7%8D%E4%BB%A5%E5%86%85%E8%83%BD%E7%A9%B7%E4%B8%BE%E5%90%97%22%7D%0A%20%20J%20--%3E%7C%E5%90%A6%7C%20R%5B%22%E5%85%88%E6%94%B9%E6%95%B0%E6%8D%AE%E6%A8%A1%E5%9E%8B%EF%BC%8C%E5%86%8D%E8%B0%88%E9%80%89%E5%9E%8B%22%5D%0A%20%20J%20--%3E%7C%E6%98%AF%7C%20W%7B%22%E5%86%99%E5%85%A5%E6%98%AF%20append-only%20%E6%B4%AA%E6%B5%81%E5%90%97%22%7D%0A%20%20W%20--%3E%7C%E6%98%AF%7C%20C%5B%22%E5%88%97%E5%AD%98%E5%80%99%E9%80%89%EF%BC%9AClickHouse%20%2F%20Parquet%2BArrow%20%2F%20kdb%2B%22%5D%0A%20%20W%20--%3E%7C%E5%90%A6%7C%20T%5B%22%E6%97%B6%E5%BA%8F%E6%88%96%E5%85%B3%E7%B3%BB%E5%80%99%E9%80%89%EF%BC%9ATimescale%20%2F%20Postgres%22%5D%0A%20%20C%20--%3E%20B%5B%22%E8%87%AA%E5%BB%BA%E5%9F%BA%E5%87%86%EF%BC%9A%E4%BA%94%E6%9F%A5%E8%AF%A2%E4%B9%98%E5%AE%9E%E9%99%85%E9%87%8F%E7%BA%A7%22%5D%0A%20%20T%20--%3E%20B%0A%20%20B%20--%3E%20S%5B%22%E9%AA%8C%E6%94%B6%EF%BC%9A%E5%B8%A6%E5%AE%BD%E3%80%81%E5%8E%8B%E7%BC%A9%E3%80%81as-of%E3%80%81%E6%88%90%E6%9C%AC%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[t("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"列存赢在扫描的原因是列裁剪：一次截面回测往往只读几十列中的几列，行存必须整行过内存，列存把有效 IO 缩到十分之一量级。时间戳列做 delta-of-delta、浮点价做 Gorilla 类编码后，每样本可压到字节级——Gorilla 在生产中报告平均约 1.37 字节每样本；市场数据的压缩收益与之同源：价格在一个 tick 内不变、时间戳高度局部。分区键几乎总该是日期乘标的，因为五种查询无一不带日期范围，分区裁剪把扫描限制在当日目录。最关键的是 append-only 与版本化天然合拍：引擎不需要 UPDATE，供应商修正写成新分区新版本，旧版本不可变——这正是本课程版本化一课的地基。选型因此不是性能问题而是不变量问题：引擎替你守住的 append-only、分区、列式三条不变量，是后面每一课复用的前提。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"Gorilla（Facebook 生产监控系统）报告平均 1.37 字节每样本、约十倍于定宽浮点编码的压缩。市场数据的压缩比同样依赖编码与样本：引用任何「通用压缩比」之前，先在自己一段真实 tick 上重测。")],-1)),E[6]||(E[6]=a("p",null,[a("span",{class:"marginnote"},"数字实例：一张 40 列的行情宽表，截面回测只读其中 3 列（日期、收盘价、成交量）。行存按行存储，必须把 40 列整行读进内存，IO 是 40 份；列存只碰 3 个列文件，有效 IO 是 3 份——还没算列内压缩再省下的部分。这就是同一段数据在两类引擎上回测差出量级的几何原因，与硬件快慢无关。")],-1)),(A(),r(s,null,{default:e(()=>[o(B,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20ROW%5B%22%E8%A1%8C%E5%AD%98%E8%AF%BB%E8%B7%AF%E5%BE%84%22%5D%0A%20%20%20%20RQ%5B%22%E6%9F%A5%E8%AF%A2%EF%BC%9A3%20%E5%88%97%E6%88%AA%E9%9D%A2%E5%9B%A0%E5%AD%90%22%5D%20--%3E%20RS%5B%22%E9%80%90%E8%A1%8C%E8%AF%BB%E6%95%B4%E8%A1%8C%2040%20%E5%88%97%22%5D%0A%20%20%20%20RS%20--%3E%20RD%5B%22%E4%B8%A2%E5%BC%83%2037%20%E5%88%97%22%5D%0A%20%20%20%20RD%20--%3E%20RF%5B%22%E5%89%A9%E4%BD%99%E6%95%B0%E6%8D%AE%E8%BF%9B%E8%AE%A1%E7%AE%97%22%5D%0A%20%20end%0A%20%20subgraph%20COL%5B%22%E5%88%97%E5%AD%98%E8%AF%BB%E8%B7%AF%E5%BE%84%22%5D%0A%20%20%20%20CQ%5B%22%E5%90%8C%E4%B8%80%E6%9F%A5%E8%AF%A2%22%5D%20--%3E%20CP%5B%22%E5%88%86%E5%8C%BA%E8%A3%81%E5%89%AA%EF%BC%9A%E5%8F%AA%E5%BC%80%E5%BD%93%E6%97%A5%E7%9B%AE%E5%BD%95%22%5D%0A%20%20%20%20CP%20--%3E%20CPr%5B%22%E5%88%97%E8%A3%81%E5%89%AA%EF%BC%9A%E5%8F%AA%E8%AF%BB%203%20%E4%B8%AA%E5%88%97%E6%96%87%E4%BB%B6%22%5D%0A%20%20%20%20CPr%20--%3E%20CD%5B%22%E8%A7%A3%E5%8E%8B%203%20%E5%88%97%E8%BF%9B%E8%AE%A1%E7%AE%97%22%5D%0A%20%20end%0A%20%20RF%20-.-%3E%7C%22%E6%9C%89%E6%95%88%20IO%20%E7%BA%A6%E4%B8%BA%E4%B8%80%E8%A1%8C%E7%9A%84%E5%8D%81%E5%88%86%E4%B9%8B%E4%B8%80%22%7C%20CD%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=l('<p><span class="marginnote">常见误区：初学者容易以为分区越细越好（比如按小时甚至按标的分区），实际上分区过细会产生海量小文件，元数据开销和打开文件的固定成本反而拖垮扫描。分区键要对齐查询形状——五种查询无一不带日期范围，所以「日期（乘标的）」几乎总是正确粒度，而不是越细越好。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不宣布「最好的数据库」：引擎谱系随硬件与生态漂移，这张表三年后要重画。不写实时行情总线——分发与延迟是<a href="/quant/sip-vs-direct">SIP vs 直连行情</a>的对象，本课以落盘为界。也不把裸 Parquet 当成「平台」：没有元数据目录与 as-of 函数，研究者会各自造轮子；下一课起的清洗与点时库，就是把裸存储补成平台的两步。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>选型判据是查询形状，不是泛化跑分：先把团队查询收成五种以内。</li><li>市场数据的写形状是 append-only 洪流，读形状是切片、列聚合、as-of、窗口、rank 五种。</li><li>列存加轻量编码把扫描带宽抬一个量级，分区键几乎总是日期乘标的。</li><li>引擎守住的三条不变量——append-only、分区、列式——是清洗、版本化与点时库的地基。</li><li>出处：Pelkonen 等, <em>Gorilla</em>, VLDB 2015；kdb+、ClickHouse、TimescaleDB 公开文档；站内<a href="/quant/fml-feature-store-deep">特征存储的深入</a>的留白与判据。</li></ul>',5))])}const b=n(p,[["render",C]]);export{h as __pageData,b as default};
